CREATE TABLE classifieds_records ( kind TEXT NOT NULL CHECK (kind IN ('category','subcategory','profile','ad','catalog','slugClaim','operation','audit','adCleanup','photoCleanup','retirement')), namespace TEXT NOT NULL DEFAULT '', id TEXT NOT NULL, body TEXT NOT NULL CHECK (json_valid(body) AND json_type(body) = 'object' AND length(CAST(body AS BLOB)) <= 1000000), version TEXT NOT NULL, source_version TEXT, normalized_title TEXT, profile_id TEXT GENERATED ALWAYS AS (CASE WHEN kind IN ('profile','catalog') THEN id ELSE coalesce(json_extract(body, '$.advertiserProfileId'), json_extract(body, '$.profileId')) END) STORED, category_id TEXT GENERATED ALWAYS AS (json_extract(body, '$.categoryId')) STORED, owner_id TEXT GENERATED ALWAYS AS (json_extract(body, '$.userId')) STORED, slug TEXT GENERATED ALWAYS AS (json_extract(body, '$.slug')) STORED, PRIMARY KEY (kind, namespace, id), CHECK (kind NOT IN ('category','profile','ad','catalog') OR namespace = ''), CHECK (kind != 'subcategory' OR namespace = category_id) );
CREATE INDEX classifieds_profile ON classifieds_records (kind, profile_id, namespace, id);
CREATE INDEX classifieds_category ON classifieds_records (kind, category_id, namespace, id);
CREATE INDEX classifieds_owner ON classifieds_records (kind, owner_id, namespace, id);
CREATE INDEX classifieds_profile_title ON classifieds_records (kind, normalized_title, namespace, id);
CREATE UNIQUE INDEX classifieds_category_slug ON classifieds_records (slug) WHERE kind = 'category';
CREATE UNIQUE INDEX classifieds_subcategory_slug ON classifieds_records (category_id, slug) WHERE kind = 'subcategory';
CREATE INDEX classifieds_audit_expiry ON classifieds_records (json_extract(body, '$.expiresAt')) WHERE kind = 'audit';
/* Epoch rows outlive content so create/remove/recreate cannot evade a read guard. */ CREATE TABLE classifieds_epochs (scope TEXT PRIMARY KEY, version INTEGER NOT NULL);
CREATE TRIGGER classifieds_insert_epoch AFTER INSERT ON classifieds_records BEGIN INSERT INTO classifieds_epochs (scope, version) SELECT scope, 1 FROM ( SELECT json_array('kind', NEW.kind) scope UNION SELECT json_array('point', NEW.kind, NEW.namespace, NEW.id) UNION SELECT json_array('all') UNION SELECT CASE WHEN NEW.kind IN ('profile','ad','catalog') AND NEW.profile_id IS NOT NULL AND NEW.profile_id != '' THEN json_array('identity', NEW.profile_id) END ) WHERE scope IS NOT NULL ON CONFLICT(scope) DO UPDATE SET version = version + 1; END;
CREATE TRIGGER classifieds_update_epoch AFTER UPDATE ON classifieds_records BEGIN INSERT INTO classifieds_epochs (scope, version) SELECT scope, 1 FROM ( SELECT json_array('kind', NEW.kind) scope UNION SELECT json_array('point', NEW.kind, NEW.namespace, NEW.id) UNION SELECT json_array('all') UNION SELECT CASE WHEN OLD.kind IN ('profile','ad','catalog') AND OLD.profile_id IS NOT NULL AND OLD.profile_id != '' THEN json_array('identity', OLD.profile_id) END UNION SELECT CASE WHEN NEW.kind IN ('profile','ad','catalog') AND NEW.profile_id IS NOT NULL AND NEW.profile_id != '' THEN json_array('identity', NEW.profile_id) END ) WHERE scope IS NOT NULL ON CONFLICT(scope) DO UPDATE SET version = version + 1; END;
CREATE TRIGGER classifieds_delete_epoch AFTER DELETE ON classifieds_records BEGIN INSERT INTO classifieds_epochs (scope, version) SELECT scope, 1 FROM ( SELECT json_array('kind', OLD.kind) scope UNION SELECT json_array('point', OLD.kind, OLD.namespace, OLD.id) UNION SELECT json_array('all') UNION SELECT CASE WHEN OLD.kind IN ('profile','ad','catalog') AND OLD.profile_id IS NOT NULL AND OLD.profile_id != '' THEN json_array('identity', OLD.profile_id) END ) WHERE scope IS NOT NULL ON CONFLICT(scope) DO UPDATE SET version = version + 1; END;
CREATE TABLE classifieds_contacts ( profile_id TEXT NOT NULL, contact TEXT NOT NULL, PRIMARY KEY (profile_id, contact) );
CREATE INDEX classifieds_contact_lookup ON classifieds_contacts (contact, profile_id);
CREATE TABLE classifieds_artifacts ( ad_id TEXT NOT NULL, path TEXT NOT NULL, job_id TEXT NOT NULL, linked INTEGER NOT NULL, pending INTEGER NOT NULL, completed INTEGER NOT NULL, reserved INTEGER NOT NULL, expires_at INTEGER, ownership TEXT NOT NULL CHECK (ownership IN ('owned','legacy','foreign')), PRIMARY KEY (ad_id, path) );
CREATE INDEX classifieds_artifact_job ON classifieds_artifacts (job_id);
CREATE TRIGGER classifieds_ad_artifacts AFTER DELETE ON classifieds_records WHEN OLD.kind = 'ad' BEGIN DELETE FROM classifieds_artifacts WHERE ad_id = OLD.id; END;
CREATE TRIGGER classifieds_profile_contacts AFTER DELETE ON classifieds_records WHEN OLD.kind = 'profile' BEGIN DELETE FROM classifieds_contacts WHERE profile_id = OLD.id; END;
CREATE TABLE classifieds_receipts ( actor_id TEXT NOT NULL, operation_key TEXT NOT NULL, intent TEXT NOT NULL, result TEXT NOT NULL CHECK (json_valid(result)), PRIMARY KEY (actor_id, operation_key) );
CREATE TRIGGER classifieds_receipt_epoch AFTER INSERT ON classifieds_receipts BEGIN INSERT INTO classifieds_epochs VALUES ('["all"]', 1) ON CONFLICT(scope) DO UPDATE SET version = version + 1; END;
/* A failing guard aborts the entire batch, including its writes and receipts. */ CREATE TABLE classifieds_assertions ( token TEXT NOT NULL, passed INTEGER NOT NULL CONSTRAINT classifieds_conflict CHECK (passed = 1) );
